use indicators::{CyclicProgress, Format, ProgressDisplay};

fn main() {
    let _args: Vec<String> = std::env::args().collect();

    let mut cyclic1 = CyclicProgress::new(5);
    let mut cyclic2 = CyclicProgress::new(10);
    let mut cyclic3 = CyclicProgress::new(15);

    for _ in 0..3 {
        cyclic1.next();
    }
    for _ in 0..6 {
        cyclic2.next();
    }
    for _ in 0..9 {
        cyclic3.next();
    }

    println!("{}", cyclic1.r#str());
    println!("{}", cyclic2.r#str());
    println!("{}", cyclic3.r#str());

    let mut displays = [
        ProgressDisplay::default(),
        ProgressDisplay::default(),
        ProgressDisplay::default(),
    ];
    displays[0] = ProgressDisplay::new(50);
    displays[1] = ProgressDisplay::new(100);
    displays[2] = ProgressDisplay::new(200);

    displays[0].update(25);
    displays[1].update(75);
    displays[2].update(150);

    for display in &displays {
        println!("{}", display.display());
    }

    displays[0].increment(5);
    displays[1].increment(10);
    displays[2].increment(20);

