    println!("{}", Format::percentage_with_precision(0.5, 2));
    println!("{}", Format::percentage_with_precision(0.75, 3));
    println!("{}", Format::progress(25, 100));
    println!("{}", Format::progress(50, 100));
    println!("{}", Format::progress(75, 100));
}

